#!/usr/bin/env python3
# gate: hermetic   (reads two files; touches nothing live)
"""docs/api-routes.md lists every route of the agent API (generated by scripts/api_routes.py).
Run: python3 scripts/test_api_routes.py
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

import api_routes  # noqa: E402

passed = failed = 0


def check(label, ok):
    global passed, failed
    passed, failed = passed + bool(ok), failed + (not ok)
    print(f"  [{'PASS' if ok else 'FAIL'}] {label}")


rs = api_routes.routes(api_routes.SERVER.read_text())
paths = {(m, p) for m, p, _ in rs}
check("finds the routes (over 100)", len(rs) > 100)
for want in (("GET", "/health"), ("POST", "/v1/files"), ("GET", "/v1/home"), ("PATCH", "/v1/devices/self"),
             ("POST", "/v1/places/confirm")):
    check(f"includes {want[0]} {want[1]}", want in paths)
check("no retired route (qwen3coder-mode)", not any("qwen3coder" in p for _, p in paths))
check("docs/api-routes.md is current (run python3 scripts/api_routes.py)",
      api_routes.DOC.exists() and api_routes.DOC.read_text() == api_routes.render(rs))

print(f"\n{passed} passed, {failed} failed")
sys.exit(1 if failed else 0)
